#define fade 0.9
#define pi 3.14159

struct Path
{
    vec2 s;
    vec2 e;
};

float draw_path(vec2 x, Path p, float width)
{
    vec2 x0 = p.s;
    vec2 x1 = p.e;

    // parameter along path
    float s = dot(x1-x0,x-x0)/dot(x1-x0,x1-x0);

    if (s > 1. || s < 0.)
    {
        return 0.;
    }

    vec2 xs = x0 + s*(x1 - x0);

    // height above path squared
    float h = length(x - xs);

    if (abs(h) < width)
    {

        return mix(fade, 1., s);
    }
    else
    {
        return 0.;
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from -.5 to .5)
    vec2 uv = (fragCoord - iResolution.xy/2.)/iResolution.y;

    // Time varying pixel color
    vec3 col = vec3(0.);

    float t = floor(iTime*60.);

    float f1 = 2.*pi*log(1.+t/2000.);
    float r1 = 0.48;

    int i_max = 40;

    float fade_i = 1.;

    for (int i = 0; i < i_max; i++)
    {
        float t0 = t-float(i+1);
        float t1 = t-float(i);

        vec2 x0 = r1*vec2(cos(f1*t0), sin(f1*t0));
        vec2 x1 = r1*vec2(cos(f1*t1), sin(f1*t1));

    	Path p1 = Path(x0, x1);

    	col += fade_i * draw_path(uv, p1, 0.002);

        fade_i *= fade;
    }

    // Output to screen
    fragColor = vec4(col,1.0);
}
